// DO NOT EDIT: This file was auto generated by egautotest.

func TestBuildContainer(t *testing.T) {
	ctx, done := testx.Context(t)
	defer done()

	require.Error(t, egdebuild.Prepare(egdebuild.Runner(), nil)(ctx, egtest.Op()), ffierrors.ErrNotImplemented)
	s := testx.ReadMD5(os.TempDir(), "Containerfile")
	require.Equal(t, testx.ReadMD5(filepath.Join(".debian", "Containerfile")), s)
}

func TestOptionRuntime(t *testing.T) {
	t.Run("applied function is used as the runtime adjustment", func(t *testing.T) {
		called := false
		cfg := egdebuild.New("testpkg", "ubuntu", t.TempDir())
		cfg = egdebuild.From(cfg, egdebuild.Option.Runtime(func(cmd shell.Command) shell.Command {
			called = true
			return cmd
		}))

		_ = egdebuild.Runtime(cfg)
		require.True(t, called)
	})

	t.Run("default identity is used when no runtime option is applied", func(t *testing.T) {
		cfg := egdebuild.New("testpkg", "ubuntu", t.TempDir())

		out := egdebuild.Runtime(cfg)
		require.NotNil(t, &out)
	})

	t.Run("option can be passed directly to Runtime", func(t *testing.T) {
		called := false
		cfg := egdebuild.New("testpkg", "ubuntu", t.TempDir())

		_ = egdebuild.Runtime(cfg, egdebuild.Option.Runtime(func(cmd shell.Command) shell.Command {
			called = true
			return cmd
		}))
		require.True(t, called)
	})

	t.Run("later option overrides earlier option", func(t *testing.T) {
		first := false
		second := false
		cfg := egdebuild.New("testpkg", "ubuntu", t.TempDir())
		cfg = egdebuild.From(cfg,
			egdebuild.Option.Runtime(func(cmd shell.Command) shell.Command {
				first = true
				return cmd
			}),
			egdebuild.Option.Runtime(func(cmd shell.Command) shell.Command {
				second = true
				return cmd
			}),
		)

		_ = egdebuild.Runtime(cfg)
		require.False(t, first)
		require.True(t, second)
	})
}
